from PIL import Image
p='/app/output/trace/001_fingers_grip'; meta=json.load(open(p+'/meta.json'))
for cam in ['front','side','oblique']:
 I=np.array(Image.open(p+'/last/'+cam+'.jpg'));D=np.load(p+'/depth_'+cam+'.npy');D=D[-1] if D.ndim==3 else D
 C=np.array(meta['cameras'][cam]['cam2world_gl']);K=np.array(meta['cameras'][cam]['intrinsic_cv'])
 yy,xx=np.indices(I.shape[:2]);mask=(I.max(2)-I.min(2)<30)&(I.mean(2)<140)&(D<1.4)&(D>0.7)
