 if cam=='oblique':mask &= (yy>100)&(yy<200)&(xx>60)&(xx<200)
 ys,xs=np.nonzero(mask);pts=[]
 for x,y in zip(xs,ys):
  z=D[y,x];v=np.array([(x-K[0,2])/K[0,0]*z,-(y-K[1,2])/K[1,1]*z,-z,1.]);pts.append((C@v)[:3])
 pts=np.array(pts)
