p='/app/output/trace/025_manual_joint_target';cam='oblique';I=np.array(Image.open(p+'/last/'+cam+'.jpg')).astype(int);D=np.load(p+'/depth_'+cam+'.npy');D=D[-1] if D.ndim==3 else D;m=json.load(open(p+'/meta.json'));C=np.array(m['cameras'][cam]['cam2world_gl']);K=np.array(m['cameras'][cam]['intrinsic_cv'])
for y in range(115,151,3):
 inds=[]
 for x in range(120,191):
  rgb=I[y,x];d=float(D[y,x]);
  if rgb.mean()<190 and rgb.max()-rgb.min()<70 and d<1.23:
   v=np.array([(x-K[0,2])/K[0,0]*d,-(y-K[1,2])/K[1,1]*d,-d,1]);w=C@v
   if w[2]>.54: inds.append((x,rgb.mean(),d,w[:3]))
 if inds:
  xs=[a[0] for a in inds];a=inds[len(inds)//2]
  print('row',y,'x',min(xs),max(xs),'mid',a[0],round(a[1]),round(a[2],3),np.round(a[3],3))
